  <section class="card qr"><div class="card-header"><div><h2>Quiz results</h2><p>How many people got online through the quiz, and what they answered.</p></div><div class="segmented">${[7,30,90].map(n=>`<button type="button" data-qr="${n}" class="${pages.qrDays===n?'active':''}">${n} days</button>`).join('')}</div></div>
   <div class="qr-tiles"><div><b>${R.attempts}</b><small>Attempts</small></div><div><b>${R.passed}</b><small>Passed (got free time)</small></div><div><b>${R.passRate}%</b><small>Pass rate</small></div></div>
   ${R.quizzes.length?`<div class="qr-list">${R.quizzes.map(q=>{const mx=Math.max(1,...q.picks);return `<div class="qr-q"><strong>${H(q.question)}</strong><small>${q.attempts} attempts · ${q.passed} passed</small><ul class="rp-hbars">${q.options.map((o,i)=>`<li><span>${H(o)}${q.answer===i?' ✓':''}</span><div><i style="width:${q.picks[i]/mx*100}%"></i></div><b>${q.picks[i]}</b></li>`).join('')}</ul></div>`;}).join('')}</div>`:'<p class="muted" style="padding:0 18px 18px">Nothing yet. Results appear once customers take a quiz on the WiFi page.</p>'}</section>
