  const planSel=v=>`<select name="planId">${hp.map(p=>`<option value="${H(p.id)}" ${v===p.id?'selected':''}>${H(p.name)} (${p.downloadMbps} Mbps)</option>`).join('')}</select>`;
  const adForm=a=>{a=a||{active:true,seconds:15,weight:1,earn:{enabled:false,minutes:10}};radiusForm(a.id?'Edit advert':'New advert','Images and links must use https://.',`<div class="form-grid"><label>Title<input name="title" maxlength="60" required value="${H(a.title||'')}"></label><label>Advertiser<input name="advertiser" maxlength="60" value="${H(a.advertiser||'')}"></label><label>Image link (https)<input name="imageUrl" value="${H(a.imageUrl||'')}"></label><label>Advertiser link (https)<input name="link" value="${H(a.link||'')}"></label><label>Show from<input name="from" type="datetime-local" value="${dt(a.from)}"></label><label>Show until<input name="until" type="datetime-local" value="${dt(a.until)}"></label><label>How often (1–10)<input name="weight" type="number" min="1" max="10" value="${a.weight}"></label><label>Priority tier<select name="tier">${[[1,'1: shown first'],[2,'2: normal'],[3,'3: only when nothing else']].map(([v,l])=>`<option value="${v}" ${(a.tier||2)===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Delivery target (views, 0 = no limit)<input name="target" type="number" min="0" value="${a.target||0}"><small class="muted">Spread evenly between Show from and Show until.</small></label><label>Max views per device per day (0 = no limit)<input name="perDevice" type="number" min="0" max="50" value="${a.perDevice||0}"></label><label>Viewing time (seconds)<input name="seconds" type="number" min="5" max="120" value="${a.seconds}"></label></div><label>Text<textarea name="text" maxlength="240" rows="2">${H(a.text||'')}</textarea></label><fieldset><legend>Show on (none ticked = all)</legend>${['phone','tablet','computer'].map(k=>`<label><input type="checkbox" name="dev" value="${k}" ${(a.devices||[]).includes(k)?'checked':''}><span>${k[0].toUpperCase()+k.slice(1)}s</span></label>`).join('')}${['android','ios','windows','mac','linux'].map(k=>`<label><input type="checkbox" name="osx" value="${k}" ${(a.os||[]).includes(k)?'checked':''}><span>${{android:'Android',ios:'iPhone/iPad',windows:'Windows',mac:'Mac',linux:'Linux'}[k]}</span></label>`).join('')}</fieldset><label class="check-label"><input type="checkbox" name="active" ${a.active?'checked':''}> Showing</label><label class="check-label"><input type="checkbox" name="earn" ${a.earn.enabled?'checked':''}> Watching it earns free minutes</label><div class="form-grid"><label>Free minutes<input name="minutes" type="number" min="1" max="240" value="${a.earn.minutes||10}"></label><label>At the speed of${planSel(a.earn.planId)}</label></div>`,a.id?'Save':'Create',inp=>api(a.id?'engage/ads/'+a.id:'engage/ads',a.id?'PATCH':'POST',{...inp,active:inp.active==='on',from:inp.from?Date.parse(inp.from+':00+03:00'):'',until:inp.until?Date.parse(inp.until+':00+03:00'):'',earn:{enabled:inp.earn==='on',minutes:inp.minutes,planId:inp.planId},devices:[...$('#editor-form').querySelectorAll('[name=dev]:checked')].map(x=>x.value),os:[...$('#editor-form').querySelectorAll('[name=osx]:checked')].map(x=>x.value)}).then(()=>{toast('Saved');pages.engage(id);}));};
  const quizForm=q=>{q=q||{active:true,options:['','',''],answer:0,earn:{minutes:10}};radiusForm(q.id?'Edit quiz':'New quiz','A right answer connects the device for free.',`<label>Question<input name="question" maxlength="200" required value="${H(q.question||'')}"></label><label>Answers, one per line (2–6). For a picture question add the image link after a bar: <code>Coca-Cola | https://…/coke.jpg</code><textarea name="options" rows="5" required>${H(q.options.map((o,i)=>q.images?.[i]?o+' | '+q.images[i]:o).join('\n'))}</textarea></label><div class="form-grid"><label>Right answer<select name="answer"><option value="any" ${q.answer===-1?'selected':''}>No right answer: any pick connects (opinion question)</option>${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${q.answer===n-1?'selected':''}>Answer ${n}</option>`).join('')}</select></label><label>Free minutes<input name="minutes" type="number" min="1" max="240" value="${q.earn.minutes||10}"></label><label>At the speed of${planSel(q.earn.planId)}</label></div><label class="check-label"><input type="checkbox" name="active" ${q.active?'checked':''}> Showing</label>`,q.id?'Save':'Create',inp=>api(q.id?'engage/quizzes/'+q.id:'engage/quizzes',q.id?'PATCH':'POST',{question:inp.question,options:inp.options,answer:inp.answer==='any'?'any':Number(inp.answer)-1,active:inp.active==='on',earn:{minutes:inp.minutes,planId:inp.planId}}).then(()=>{toast('Saved');pages.engage(id);}));};
  $('#en-ad').onclick=()=>hp.length?adForm(null):toast('Create a hotspot package first');$('#en-quiz').onclick=()=>hp.length?quizForm(null):toast('Create a hotspot package first');
  for(const b of document.querySelectorAll('[data-en-ad]'))b.onclick=()=>adForm(d.ads.find(a=>a.id===b.dataset.enAd));
